{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Services — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf9f6;--ink:#222;--muted:#6f6b66;--accent:#7aa27a;--glass:rgba(255,255,255,0.6);--maxw:900px}
    html,body{height:100%}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--ink);background:linear-gradient(180deg,var(--bg),#f7f5f3);}
    .wrap{max-width:var(--maxw);margin:40px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}
    .brand{font-weight:600;letter-spacing:0.4px}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px;font-size:14px}
    .hero{background:linear-gradient(135deg,rgba(122,162,122,0.06),rgba(255,255,255,0));padding:34px;border-radius:12px;box-shadow:0 6px 18px rgba(32,30,26,0.05)}
    .hero h1{margin:0 0 8px;font-size:28px}
    .hero p{margin:0;color:var(--muted)}
    .kicker{display:inline-block;margin-top:14px;background:var(--glass);padding:8px 12px;border-radius:999px;color:var(--muted);font-size:13px}

    section{margin-top:28px;opacity:0;transform:translateY(18px);transition:opacity .6s ease,var(--trans,transform) .6s ease}
    .reveal-visible{opacity:1;transform:none}
    .grid{display:grid;grid-template-columns:1fr;gap:16px;margin-top:16px}
    .card{background:white;border-radius:10px;padding:16px;box-shadow:0 6px 18px rgba(28,28,28,0.04)}
    .price{font-weight:700;color:var(--accent)}
    .cta-row{display:flex;gap:12px;align-items:center;margin-top:18px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;text-decoration:none;border:none;cursor:pointer}
    .btn.ghost{background:transparent;color:var(--ink);border:1px solid rgba(0,0,0,0.06)}

    footer{margin-top:36px;color:var(--muted);font-size:13px}

    /* Modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(8,8,8,0.4);display:none;align-items:center;justify-content:center;padding:24px;z-index:60}
    .modal{background:white;padding:20px;border-radius:12px;max-width:560px;width:100%;box-shadow:0 10px 30px rgba(20,20,20,0.15)}
    .modal h3{margin:0 0 8px}
    .tabs{display:flex;gap:8px;margin-top:12px}
    .tab-btn{flex:1;padding:8px 10px;border-radius:8px;border:1px solid #eee;background:#fafafa;cursor:pointer}
    .control-row{display:flex;gap:8px;margin-top:12px}
    .breath-circle{width:120px;height:120px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#a7d3a7,#7aa27a);margin:12px auto;display:flex;align-items:center;justify-content:center;color:white;font-weight:700}

    /* pattern background reference */
    .pattern-area{background-image:url('assets/img/pattern.svg');background-repeat:repeat;padding:18px;border-radius:8px}

    /* reduced motion support */
    @media (prefers-reduced-motion:reduce){section{transition:none}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav aria-label="Main">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Value</a>
        <a href="about.html">About</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="hero" data-reveal>
        <h1>Offerings that meet you where you are</h1>
        <p>Plant-led scent practices and short guided sessions that may support ease, clarity, and focus. Tailored, safety-minded, and quietly effective.</p>
        <div class="kicker">Sessions, mini-practices, and blends — a hybrid approach</div>
        <div class="cta-row">
          <button class="btn" id="open-exercise">Try it now</button>
          <a class="btn ghost" href="book.html">Schedule a visit</a>
        </div>
      </section>

      <section data-reveal>
        <h2>Pillars of practice</h2>
        <div class="grid">
          <div class="card">
            <strong>Guided Consult</strong>
            <p class="muted">A one-on-one session to map preferences, sensitivities, and personal goals. Safety-first notes discussed.</p>
            <div class="price">$95 / 60 min</div>
          </div>
          <div class="card">
            <strong>Short Sessions</strong>
            <p class="muted">20–30 minute focused sessions for clarity, reset, or grounding. Great as a recurring micro-practice.</p>
            <div class="price">$45 / 30 min</div>
          </div>
          <div class="card">
            <strong>Custom Blend Design</strong>
            <p class="muted">A tailored aromatic formula to support daily rhythm. Includes dilution guidance and use notes.</p>
            <div class="price">$65 (includes 10 mL)</div>
          </div>
        </div>
      </section>

      <section class="pattern-area" data-reveal>
        <h2>What people often misunderstand</h2>
        <p class="muted">Myth: Aromas fix medical conditions. Truth: Thoughtful scent work may support wellbeing and habit. Sessions always emphasize safety, and orders include dilution and patch-test instructions.</p>
      </section>

      <section data-reveal>
        <h2>FAQ — safety and use</h2>
        <div class="card">
          <p><strong>Are these medical treatments?</strong> No. Aromatic practices described here are non-medical and described as practices that may support certain states. They are not a substitute for medical care.</p>
          <p><strong>Safety notes</strong>: Always perform a patch test. Dilute essential oils appropriately before topical use. Keep essential oils away from eyes. If pregnant, nursing, or under medical care, consult your healthcare provider before use. If you have pets, select oils that are considered pet-safe and use diffusers in ventilated spaces.</p>
          <p><strong>Patch test</strong>: Apply diluted oil to a small skin area and wait 24 hours for reactions.</p>
        </div>
      </section>

      <section data-reveal>
        <h2>Ready to begin?</h2>
        <p class="muted">Choose a session or start with a short guided practice below.</p>
        <div class="cta-row">
          <a class="btn" href="book.html">Book a session</a>
          <button class="btn ghost" id="open-exercise-2">Guided micro-practice</button>
        </div>
      </section>

    </main>

    <footer>
      <div>Call: {{PHONE}} • Email: {{EMAIL}}</div>
      <div style="margin-top:8px">Serving {{CITY}}, {{STATE}}</div>
    </footer>
  </div>

  <!-- Modal: Try it now -->
  <div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" aria-labelledby="modal-title">
      <h3 id="modal-title">Try a short practice</h3>
      <div class="tabs" role="tablist">
        <button class="tab-btn" data-tab="breath">Breathing</button>
        <button class="tab-btn" data-tab="journal">Journaling</button>
        <button class="tab-btn" data-tab="intention">Intention</button>
      </div>

      <div id="panel-breath" class="panel" hidden>
        <p>Follow a 3-step paced breathing: inhale, hold, exhale. Use the circle as a gentle guide.</p>
        <div class="breath-circle" id="breath-circle">3</div>
        <div class="control-row">
          <button class="btn" id="start-breath">Start 2-minute</button>
          <button class="btn ghost" id="stop-breath">Stop</button>
        </div>
      </div>

      <div id="panel-journal" class="panel" hidden>
        <p>Short prompt: What would a calmer version of your next hour look like?</p>
        <textarea id="journal-input" rows="5" style="width:100%;padding:8px;border-radius:8px;border:1px solid #eee"></textarea>
        <div class="control-row"><button class="btn" id="save-journal">Save</button><button class="btn ghost" id="clear-journal">Clear</button></div>
      </div>

      <div id="panel-intention" class="panel" hidden>
        <p>Choose a simple intention for the next 30 minutes.</p>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="tab-btn" data-intent="focus">Focus</button>
          <button class="tab-btn" data-intent="soft">Softness</button>
          <button class="tab-btn" data-intent="steady">Steady breath</button>
        </div>
        <div style="margin-top:12px"><strong id="chosen-intent"></strong></div>
      </div>

      <div style="display:flex;justify-content:flex-end;margin-top:12px;gap:8px">
        <button class="btn ghost" id="close-modal">Close</button>
        <a class="btn" href="book.html">Book a guided consult</a>
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){items.forEach(i=>i.classList.add('reveal-visible'));return}
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal-visible');obs.unobserve(e.target)}},{threshold:0.12});
      items.forEach(i=>obs.observe(i));
    })();

    // Modal + guided practice
    (function(){
      const modal = document.getElementById('modal');
      const openBtns = [document.getElementById('open-exercise'),document.getElementById('open-exercise-2')];
      const closeBtn = document.getElementById('close-modal');
      const tabButtons = document.querySelectorAll('.tab-btn[data-tab]');
      const panels = {breath:document.getElementById('panel-breath'),journal:document.getElementById('panel-journal'),intention:document.getElementById('panel-intention')};
      function showModal(){modal.style.display='flex';modal.setAttribute('aria-hidden','false');activateTab('breath')}
      function hideModal(){modal.style.display='none';modal.setAttribute('aria-hidden','true')}
      openBtns.forEach(b=>b.addEventListener('click',showModal));
      closeBtn.addEventListener('click',hideModal);
      modal.addEventListener('click',e=>{if(e.target===modal)hideModal()});

      tabButtons.forEach(btn=>btn.addEventListener('click',()=>{activateTab(btn.dataset.tab)}));
      function activateTab(name){Object.values(panels).forEach(p=>p.hidden=true);panels[name].hidden=false}

      // Breathing timer
      const circle = document.getElementById('breath-circle');
      let breathTimer = null;let phase=0;let rounds=0;const sequence=[4,2,6]; // inhale,hold,exhale seconds
      document.getElementById('start-breath').addEventListener('click',()=>{
        if(breathTimer) return;
        rounds=0;phase=0;circle.textContent=sequence[phase];
        breathTimer = setInterval(()=>{
          let t = --sequence[phase];
          circle.textContent = t>0? t : '•';
          if(t<=0){phase++;if(phase>2){phase=0;rounds++;if(rounds>=6){clearInterval(breathTimer);breathTimer=null;sequence[0]=4;sequence[1]=2;sequence[2]=6;circle.textContent='Done';return}}}
        },1000);
        // reset the sequence values after starting (we mutated them above)
        sequence[0]=4;sequence[1]=2;sequence[2]=6;
      });
      document.getElementById('stop-breath').addEventListener('click',()=>{if(breathTimer){clearInterval(breathTimer);breathTimer=null;circle.textContent='Stopped'}});

      // Journal
      const jInput = document.getElementById('journal-input');
      const saveBtn = document.getElementById('save-journal');
      const clearBtn = document.getElementById('clear-journal');
      const storageKey = 'aroma_journal';
      if(localStorage.getItem(storageKey)) jInput.value = localStorage.getItem(storageKey);
      saveBtn.addEventListener('click',()=>{localStorage.setItem(storageKey,jInput.value);saveBtn.textContent='Saved';setTimeout(()=>saveBtn.textContent='Save',1200)});
      clearBtn.addEventListener('click',()=>{jInput.value='';localStorage.removeItem(storageKey)});

      // Intention
      document.querySelectorAll('.tab-btn[data-intent]').forEach(b=>b.addEventListener('click',e=>{
        document.getElementById('chosen-intent').textContent = 'Intention: ' + e.currentTarget.dataset.intent;
      }));

      // Keyboard: close on Escape
      document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideModal()}});
    })();
  </script>
</body>
</html>"} 
