<body>
  <div class="wrap">
    <header>
      <div style="font-weight:600">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Formulas</a>
        <a href="shop.html">Shop</a>
        <a href="pricing.html">Pricing</a>
        <a href="about.html">About</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section data-reveal>
        <h1>Signature blends</h1>
        <p class="intro">Hand-crafted aromatic blends curated to support brief moments of clarity, calm, or focus. Each blend includes dilution guidance and notes about pets and pregnancy.</p>
        <div class="try-row">
          <button class="btn" id="open-exercise">Try a short practice</button>
          <a class="btn light" href="shop.html">Browse shop</a>
        </div>
      </section>

      <section data-reveal>
        <div class="blend-grid">
          <div class="blend">
            <h3>Morning Stitch</h3>
            <p class="notes">Bright citrus with a warm, grounding base. May support gentle alertness.</p>
            <div class="small">Use: diffuse briefly; dilute for skin. Price: $18 / 10 mL</div>
          </div>

          <div class="blend">
            <h3>Quiet Harbor</h3>
            <p class="notes">Soft woody florals blended for a quieting presence. May support rest and reflective states.</p>
            <div class="small">Use: inhalation or diffuser. Price: $20 / 10 mL</div>
          </div>

          <div class="blend">
            <h3>Evening Stitch</h3>
            <p class="notes">Warm, resinous notes with a hint of sweet spice. May support winding down routines.</p>
            <div class="small">Use: diluted topical or room mist. Price: $22 / 10 mL</div>
          </div>

          <div class="blend">
            <h3>Focus Thread</h3>
            <p class="notes">Crisp, herbaceous edges designed for brief attention boosts. May support short-term focus.</p>
            <div class="small">Use: inhalation or diffuser. Price: $16 / 10 mL</div>
          </div>
        </div>
      </section>

      <section data-reveal>
        <h2>How blends are framed</h2>
        <p class="small">Blends are described as practices that may support certain subjective states. Labels include dilution ratios, suggested patch-test steps, and notes for households with pets or pregnant persons.</p>
      </section>

      <section data-reveal>
        <h2>Case notes — what to expect</h2>
        <div class="blend-grid">
          <div class="blend"><strong>Scenario</strong><p class="small">Short inhalation sessions paired with breathwork often feel like a small reset — clients may notice a subtle shift in tone or mood rather than an immediate cure.</p></div>
          <div class="blend"><strong>Scenario</strong><p class="small">Topical blends applied with proper dilution serve as ritual support rather than a treatment.</p></div>
        </div>
      </section>

      <section data-reveal>
        <h2>Safety
        </h2>
        <div class="blend">
          <p class="small"><strong>Patch test:</strong> Apply a diluted drop to inner forearm and wait 24 hours. <strong>Pregnancy & health:</strong> Consult care providers if pregnant, nursing, or immunocompromised. <strong>Pets:</strong> Some essential oils may be harmful to pets; see full guidance in product notes.</p>
        </div>
      </section>

      <section data-reveal>
        <h2>Find a blend</h2>
        <p class="small">Want a custom formula? Book a custom blend session or pick from the ready list in the shop.</p>
        <div style="margin-top:12px"><a class="btn" href="book.html">Custom blend</a> <a class="btn light" href="shop.html">Ready blends</a></div>
      </section>
    </main>

    <footer>
      <div style="color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</div>
      <div style="margin-top:8px;color:var(--muted)">Serving {{CITY}}, {{STATE}}</div>
    </footer>
  </div>

  <script>
    // Scroll reveal with reduced motion
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const targets = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){targets.forEach(t=>t.classList.add('reveal-visible'));return}
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal-visible');io.unobserve(e.target)}},{threshold:0.14});
      targets.forEach(t=>io.observe(t));
    })();

    // Reuse modal trigger from services (light implementation)
    document.getElementById('open-exercise')?.addEventListener('click',function(){
      // simple inline modal created for blends page to keep experience local
      const modal = document.createElement('div');
      modal.style.position='fixed';modal.style.inset='0';modal.style.display='flex';modal.style.alignItems='center';modal.style.justifyContent='center';modal.style.background='rgba(0,0,0,0.45)';modal.style.zIndex=9999;
      const box = document.createElement('div');box.style.background='white';box.style.padding='18px';box.style.borderRadius='12px';box.style.maxWidth='520px';box.style.width='92%';
      box.innerHTML='<h3 style="margin-top:0">Two-minute centering</h3><p style="color:#6e6a64">Follow a calm inhale for 4s, hold 2s, exhale 6s. Repeat a few times as the circle grows and shrinks.</p><div id="mini-circle" style="width:100px;height:100px;border-radius:50%;background:linear-gradient(180deg,#ffeede,#f5c6ab);margin:12px auto;display:flex;align-items:center;justify-content:center;font-weight:700">Ready</div><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px"><button id="mini-start" style="background:#b37b7b;color:#fff;padding:8px 10px;border-radius:8px;border:none">Start</button><button id="mini-close" style="padding:8px 10px;border-radius:8px;border:1px solid #eee">Close</button></div>';
      modal.appendChild(box);document.body.appendChild(modal);
      const circle = document.getElementById('mini-circle');let timer=null,seq=[4,2,6],phase=0,rounds=0;
      document.getElementById('mini-start').addEventListener('click',()=>{if(timer) return;phase=0;rounds=0;circle.textContent=seq[phase];timer=setInterval(()=>{let t=--seq[phase];circle.textContent = t>0? t : '•';if(t<=0){phase++;if(phase>2){phase=0;rounds++;if(rounds>=4){clearInterval(timer);timer=null;circle.textContent='Done';seq=[4,2,6];return}}}},1000);seq=[4,2,6];});
      document.getElementById('mini-close').addEventListener('click',()=>{document.body.removeChild(modal);if(timer){clearInterval(timer);timer=null}});
    });
  </script>
</body>
</html>"} 
