  <div class="wrap">
    <header>
      <div style="font-weight:600">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Services</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Shop</a>
        <a href="pricing.html">Pricing</a>
        <a href="about.html">About</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section data-reveal>
        <h1>Shop — Ready blends & ritual kits</h1>
        <p class="small">Everything ships with dilution instructions and patch-test guidance. Product notes include pet and pregnancy precautions when relevant.</p>
      </section>

      <section data-reveal>
        <div class="grid">
          <div class="item">
            <h3>Morning Stitch — 10 mL</h3>
            <p class="small">Bright citrus blend. Use in diffuser or inhaler. May support gentle alertness.</p>
            <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><div class="price">$18</div><button class="btn add" data-sku="morning-10">Add</button></div>
          </div>

          <div class="item">
            <h3>Quiet Harbor — 10 mL</h3>
            <p class="small">Floral-woody blend for soft presence. May support settling and reflection.</p>
            <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><div class="price">$20</div><button class="btn add" data-sku="quiet-10">Add</button></div>
          </div>

          <div class="item">
